(()=>{'use strict';const $=id=>document.getElementById(id),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),colors=['#24644f','#ac7a35','#5c7b9d','#a27989'];let data,q,group='cnpolicy',asset='equity',n=20,selected=new Set(),currentReport=null,notes='';
const read=(k,fallback)=>{try{return JSON.parse(localStorage.getItem(k)||'null')||fallback}catch{return fallback}};
let drafts=read('eventlens-drafts',[]),saved=read('eventlens-research',[]);
function store(k,v){try{localStorage.setItem(k,JSON.stringify(v));return true}catch{$('notice').textContent='浏览器存储不可用，请导出文件备份。';return false}}
function invalidate(){currentReport=null;$('report').innerHTML='<div class="empty-state">材料或选项已变化，请重新组装对照解读。</div>';$('save').disabled=$('export').disabled=$('exportHtml').disabled=true;$('notice').textContent='';}
function allEvents(){return [...data.events,...drafts]}
function updateCatalogue(){const term=$('search').value.trim().toLowerCase();$('groups').innerHTML=Object.entries(data.groups).map(([k,g])=>`<button data-group="${k}" class="${group===k?'selected':''}" aria-pressed="${group===k}">${esc(g.name)}</button>`).join('');const rows=allEvents().filter(e=>e.group===group&&(!term||(e.title+' '+e.date+' '+e.fact).toLowerCase().includes(term))).sort((a,b)=>b.date.localeCompare(a.date));$('poolCount').textContent=`本类 ${rows.length} 条 · 首发时刻未全面核实`;$('events').innerHTML=rows.map(e=>`<button class="event-row ${q?.id===e.id?'selected':''}" data-event="${esc(e.id)}"><small>${esc(e.date)} ${e.draft?'· 用户草稿':''}</small>${esc(e.title)}</button>`).join('')||'<p class="muted">没有符合条件的事件。</p>'}
function candidates(){return allEvents().filter(c=>Lens.match(q,c).eligible).sort((a,b)=>b.date.localeCompare(a.date)).slice(0,6)}
function choose(id){q=allEvents().find(e=>e.id===id);if(!q)return;group=q.group;notes='';selected=new Set(candidates().slice(0,2).map(c=>c.id));$('confirm').checked=false;invalidate();updateCatalogue();renderFact();renderCases();renderChart();updateAssemble();try{const u=new URL(location.href);u.searchParams.set('event',q.id);history.replaceState(null,'',u)}catch{}}
function renderFact(){$('eventTitle').textContent=q.title;$('fact').textContent=q.fact;$('verification').textContent=q.verification;$('eventMeta').innerHTML=`<div><span>记录的事件日</span>${esc(q.eventDate)}</div><div><span>首次公开日期</span>${esc(q.firstPublicDate||'尚未核实')}</div><div><span>具体工具 / 发布主题</span>${esc(q.tool)}</div><div><span>主体 / 地区</span>${esc(q.subject)} · ${esc(q.region)}</div><div><span>阶段 / 统计期</span>${esc(({decision:'政策决定',data_release:'数据发布'})[q.stage]||q.stage)} · ${esc(q.period||'不适用/未记录')}</div><div><span>预期差</span>未知 · 无一致预期数据</div><div class="wide"><span>时间对齐约定</span>${esc(q.timeNote)} 实际按各资产报价表选取 ≥ ${esc(q.anchor)} 的首个报价。</div>`;$('sourceCount').textContent=`（${q.sources.length}）`;$('sources').innerHTML=q.sources.map((s,i)=>`<article class="source"><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">[E${i+1}] ${esc(s.title)} ↗</a><p>${esc(s.publisher)} · 资料发布 ${esc(s.publicationDate||'未知')}</p><p>${esc(s.role)} · ${esc(s.status)}</p></article>`).join('');}
function renderCases(){const rows=candidates();$('caseCount').textContent=`${rows.length} 条候选 / 已选 ${selected.size}`;$('cases').innerHTML=rows.length?rows.map(c=>`<article class="case ${selected.has(c.id)?'checked':''}"><label><input type="checkbox" data-case="${esc(c.id)}" ${selected.has(c.id)?'checked':''}>${esc(c.date)}</label><h3>${esc(c.title)}</h3><p class="basis">${esc(Lens.match(q,c).reason)}</p><p class="difference">关键差异：${esc(c.notes)} ${c.period&&q.period?`统计期 ${esc(c.period)} / ${esc(q.period)}。`:''}</p><p class="muted">${esc(c.verification)} · ${c.sources.length} 个来源</p><button class="quiet" data-case-source="${esc(c.id)}">查看事实与来源</button><div id="case-source-${esc(c.id)}" hidden></div></article>`).join(''):'<div class="empty-state">没有足够的同工具、同方向历史案例。可选较晚的事件，或补充资料；不会放宽条件凑案例。</div>';$('rejected').innerHTML=allEvents().filter(c=>c.group===group&&c.id!==q.id&&!Lens.match(q,c).eligible).slice(-12).map(c=>`<p>${esc(c.date)} · ${esc(c.title)}<br>未入选：${esc(Lens.match(q,c).reason)}</p>`).join('')||'<p>没有其他同类记录。</p>';}
function chosen(){return candidates().filter(c=>selected.has(c.id))}
function series(){return [q,...chosen()].map((event,i)=>({event,result:Lens.observe(data.assets[asset],event.anchor,n),color:colors[i%colors.length]}))}
function renderChart(){const a=data.assets[asset],rows=series();document.querySelectorAll('[data-asset]').forEach(b=>b.classList.toggle('selected',b.dataset.asset===asset));$('priceMeta').textContent=`${a.name} (${a.code}) · ${a.unit} · 快照截止 ${a.last} · ${asset==='gold'?'供应商最近更新：配额耗尽，保留历史报价。':'指数收盘价。'} ${a.limitations}`;$('legend').innerHTML=rows.map((r,i)=>`<span><i style="background:${r.color}"></i>${i===0?'当前':'历史'} ${esc(r.event.date)}</span>`).join('');$('metrics').innerHTML=rows.map(r=>{const x=r.result;return `<tr><td>${esc(r.event.title)}<br>${esc(r.event.date)}</td><td>${x.base?esc(x.base.date)+'<br>'+x.base.close.toFixed(2):'—'}</td><td>${x.end?esc(x.end.date)+'<br>'+x.end.close.toFixed(2):'—'}</td><td class="${x.value>=0?'positive':'negative'}">${x.value===null?'—':(x.value>0?'+':'')+x.value.toFixed(2)+'%'}</td><td>${esc(x.status==='complete'?'完整窗口':x.reason)}<br>${x.count}/${n} 条</td></tr>`}).join('');draw(rows);}
function draw(rows){const usable=rows.filter(r=>r.result.path.length),pts=usable.flatMap(r=>r.result.path);if(!pts.length){$('chart').innerHTML='<div class="empty-state">该观察范围缺少可用报价，未生成走势图。</div>';return}const W=800,H=280,L=52,R=20,T=20,B=35,minX=Math.min(-20,...pts.map(p=>p.t)),maxX=n,minY=Math.min(-.2,...pts.map(p=>p.value)),maxY=Math.max(.2,...pts.map(p=>p.value)),pad=(maxY-minY)*.12,lo=minY-pad,hi=maxY+pad,x=t=>L+(t-minX)/(maxX-minX)*(W-L-R),y=v=>T+(hi-v)/(hi-lo)*(H-T-B);let out=`<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="以基准收盘归零的累计涨跌幅，横轴为有效报价观测数"><title>各事件归一化价格路径，基准=0%</title>`;for(let i=0;i<5;i++){const v=lo+(hi-lo)*i/4;out+=`<line x1="${L}" x2="${W-R}" y1="${y(v)}" y2="${y(v)}" stroke="#e5eadd"/><text x="${L-8}" y="${y(v)+4}" text-anchor="end" font-size="11" fill="#79847a">${v.toFixed(1)}%</text>`}out+=`<line x1="${x(0)}" x2="${x(0)}" y1="${T}" y2="${H-B}" stroke="#98aa96" stroke-dasharray="4 4"/><text x="${x(0)+5}" y="${T+10}" font-size="10" fill="#647863">基准收盘</text>`;for(const t of [-20,-10,0,...(n===20?[10,20]:[n])])out+=`<text x="${x(t)}" y="${H-10}" text-anchor="middle" font-size="11" fill="#79847a">${t>0?'+':''}${t}</text>`;for(const r of usable){const path=r.result.path.map((p,i)=>(i?'L':'M')+x(p.t).toFixed(2)+' '+y(p.value).toFixed(2)).join(' ');out+=`<path d="${path}" fill="none" stroke="${r.color}" stroke-width="${r.event.id===q.id?2.7:1.8}" stroke-opacity=".95"/>`}out+='</svg>';$('chart').innerHTML=out;}
function updateAssemble(){$('assemble').disabled=!$('confirm').checked||selected.size===0;}
function renderReport(r){const rows=r.results.map((x,i)=>{const a=x.result;return `<li>[P${i+1}] ${esc(x.event.date)} · ${a.value===null?esc(a.reason)+'，不计算收益':`${esc(a.base.date)} ${a.base.close.toFixed(2)} → ${esc(a.end.date)} ${a.end.close.toFixed(2)}；${a.value.toFixed(2)}%`}。</li>`}).join('');$('report').innerHTML=`<div class="report-section"><h3><span class="label">事实</span>本次研究对象</h3><p>${esc(r.facts)} [E1] ${q.draft?'本条为用户输入，未独立核实。':esc(q.verification)}</p></div><div class="report-section"><h3><span class="label">代码计算</span>${esc(data.assets[r.assetKey].name)} · ${r.n}个报价观测</h3><ul>${rows}</ul><p>各事件的实际起止日期分别计算。以上是已观察价格变化，不代表事件造成的效果。</p></div><div class="report-section"><h3><span class="label">AI 离线预研</span>相似依据与关键差异</h3><p>${esc(r.shared)}</p><p>${esc(r.difference)}</p><ul>${chosen().map(c=>`<li>${esc(c.date)}：${esc(c.notes)} ${esc(c.verification)}。</li>`).join('')}</ul></div><div class="report-section"><h3><span class="label">研究推断 · 待验证</span>一种可能的传导解释</h3><p>${esc(r.hypothesis)}</p><p>这是一项研究假设；当前材料未验证因果关系。</p></div><div class="report-section"><h3>不确定性与数据缺口</h3><ul>${r.limits.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><p>${esc(data.assets[r.assetKey].limitations)}</p></div><div class="report-section"><h3>本次引用</h3>${r.sources.map((s,i)=>`<p>[E${i+1}] <a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)}</a> · ${esc(s.role)} · ${esc(s.status)}</p>`).join('')}</div><label>我的修订与待核事项<textarea id="researchNotes" class="research-notes" rows="3" maxlength="4000" placeholder="写下你不同意的解释、需要补查的来源…">${esc(notes)}</textarea></label><p class="muted">报告组装时间 ${esc(new Date(r.createdAt).toLocaleString('zh-CN'))} · 数据准备 ${esc(data.preparedAt)}。未进行在线模型调用。</p>`;}
function assemble(){if(!$('confirm').checked||!chosen().length)return;currentReport=Lens.report(data,q,chosen(),asset,n);renderReport(currentReport);$('save').disabled=$('export').disabled=$('exportHtml').disabled=false;$('notice').textContent='已按当前案例与窗口组装；你可以修订并保存。';}
function capture(){return {...currentReport,title:q.title,notes:$('researchNotes')?.value||'',queryEvent:q,caseEvents:chosen(),asset:data.assets[asset].name,dataPreparedAt:data.preparedAt,method:'离线AI预研片段 + 确定性报价计算；无在线模型调用'}}
function download(name,body,type){const blob=new Blob([body],{type}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),3000)}
function exportHtml(r){const content=$('report').innerHTML.replace(/<textarea[\s\S]*?<\/textarea>/,'<p>'+esc(r.notes)+'</p>');download('事件镜研究简报.html',`<!doctype html><html lang="zh-CN"><meta charset="utf-8"><title>${esc(r.title)}</title><style>body{max-width:850px;margin:40px auto;padding:20px;font:15px/1.8 system-ui;color:#17352f}h3{border-bottom:1px solid #ddd;padding-bottom:8px}.label{font-size:11px;color:#567}a{overflow-wrap:anywhere}</style><h1>${esc(r.title)}</h1><p>${esc(r.method)}</p>${content}</html>`,'text/html;charset=utf-8')}
function updateSaved(){$('savedCount').textContent=saved.length;}
function openSaved(){$('savedList').innerHTML=saved.length?saved.map((r,i)=>`<article class="saved-item"><strong>${esc(r.title)}</strong><p>${esc(new Date(r.createdAt).toLocaleString('zh-CN'))} · ${esc(r.asset)} · ${r.n}条观测 · ${r.cases.length}个对照</p><p>${esc(r.notes||'尚无个人修订')}</p><button class="outline" data-restore="${i}">恢复研究选项</button><button class="quiet" data-download="${i}">下载备份</button></article>`).join(''):'<div class="empty-state">还没有保存的研究。</div>';$('savedDialog').showModal();}
document.addEventListener('click',ev=>{const b=ev.target.closest('button');if(!b)return;if(b.dataset.group){group=b.dataset.group;$('search').value='';const defaults={cnpolicy:'LPR-20241021',fed:'RECENT-20241218-FOMC',cpi:'RECENT-20250309-PRICES'};choose(defaults[group]||allEvents().find(e=>e.group===group).id)}if(b.dataset.event)choose(b.dataset.event);if(b.dataset.asset){asset=b.dataset.asset;invalidate();renderChart()}if(b.dataset.caseSource){const c=allEvents().find(e=>e.id===b.dataset.caseSource),el=$('case-source-'+c.id);el.hidden=!el.hidden;el.innerHTML=`<p>${esc(c.fact)}</p>${c.sources.map(s=>`<p><a target="_blank" rel="noopener noreferrer" href="${esc(s.url)}">${esc(s.title)} ↗</a><br>${esc(s.status)}</p>`).join('')}`}if(b.dataset.close)$(b.dataset.close).close();if(b.dataset.restore){const r=saved[Number(b.dataset.restore)];if(!allEvents().some(e=>e.id===r.eventId)){drafts.push(r.queryEvent);store('eventlens-drafts',drafts)}choose(r.eventId);asset=r.assetKey;n=r.n;$('window').value=n;selected=new Set(r.cases);notes=r.notes;$('confirm').checked=true;renderCases();renderChart();updateAssemble();assemble();$('savedDialog').close()}if(b.dataset.download)download('事件镜研究备份.json',JSON.stringify(saved[Number(b.dataset.download)],null,2),'application/json');});
document.addEventListener('change',ev=>{if(ev.target.dataset.case){if(ev.target.checked)selected.add(ev.target.dataset.case);else selected.delete(ev.target.dataset.case);invalidate();renderCases();renderChart();updateAssemble()}});
$('search').addEventListener('input',updateCatalogue);$('confirm').onchange=updateAssemble;$('window').onchange=()=>{n=Number($('window').value);invalidate();renderChart()};$('assemble').onclick=assemble;$('savedBtn').onclick=openSaved;$('draftBtn').onclick=()=>{$('draftDialog').showModal()};$('save').onclick=()=>{const r=capture();saved.unshift(r);saved=saved.slice(0,30);if(store('eventlens-research',saved)){$('notice').textContent='已保存在当前浏览器研究档案。';updateSaved()}};$('export').onclick=()=>download('事件镜研究.json',JSON.stringify(capture(),null,2),'application/json');$('exportHtml').onclick=()=>exportHtml(capture());
$('draftForm').onsubmit=ev=>{ev.preventDefault();const f=Object.fromEntries(new FormData(ev.target));try{if(/买入|卖出|荐股|目标价|收益承诺|保证.{0,8}收益|必涨/.test(f.fact))throw Error('请填写事件事实，买卖指令或收益保证不进入研究事实');const u=new URL(f.url);if(!Lens.publicUrl(f.url))throw Error('只接受不含凭据的公开 HTTP/HTTPS 地址');if(!Lens.day(f.date)||f.date<data.scope[0]||f.date>data.scope[1])throw Error('日期须在本次研究范围内');if(f.group==='cpi'&&f.direction!=='release')throw Error('CPI类型请选择“统计发布”方向');const d={id:'draft-'+crypto.randomUUID(),...data.groups[f.group],group:f.group,date:f.date,eventDate:f.date,firstPublicDate:null,firstPublicTime:null,anchor:new Date(Date.parse(f.date)+86400000).toISOString().slice(0,10),direction:f.direction,title:f.title,fact:f.fact,verification:'用户提供，尚未独立核实',draft:true,period:null,stage:f.group==='cpi'?'data_release':'decision',timeNote:'用户填写日期，按次日开始选报价；尚未核对首次公开时间。',notes:'用户材料待核。主体、具体工具与方向由表单指定，不能视为模型已验证。',sources:[{title:'用户提供的材料',publisher:'用户输入',url:u.href,publicationDate:null,role:'用户提供，未自动访问',status:'尚未独立核实'}]};drafts.push(d);if(drafts.length>30)drafts.shift();store('eventlens-drafts',drafts);$('draftDialog').close();choose(d.id)}catch(e){$('draftError').textContent=e.message}};
fetch('data.json').then(r=>{if(!r.ok)throw Error('资料文件读取失败：'+r.status);return r.json()}).then(d=>{if(!d.events?.length||!d.assets?.gold||!d.assets?.equity)throw Error('资料格式或行情字段不完整');data=d;$('eventCount').textContent=d.events.length;$('dataLimits').textContent=d.coverage+' '+d.rights;$('loading').hidden=true;$('workspace').hidden=false;updateSaved();const id=new URL(location.href).searchParams.get('event');choose(d.events.some(e=>e.id===id)?id:'LPR-20241021')}).catch(e=>{$('loading').hidden=true;$('error').hidden=false;$('error').textContent='研究资料暂不可用。'+e.message+'。没有生成替代行情或AI结论。请刷新重试。'});
})();
